"""Tests for registry module."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict

import pytest

from artifact_manager.registry import (
    LocationNotFoundError,
    RegistryValidationException,
    load_registry,
    match_location,
    validate_registry,
)


class TestRegistryValidation:
    """Test registry validation."""

    def test_rejects_non_object_root(self):
        """Registry root must be an object."""
        errors = validate_registry([])
        assert len(errors) == 1
        assert errors[0].error == "registry root must be an object mapping location keys to definitions"

    def test_rejects_non_string_keys(self):
        """Location keys must be strings."""
        errors = validate_registry({123: {"domain": "test"}})
        assert len(errors) > 0
        assert any("location key must be a string" in e.error for e in errors)

    def test_rejects_empty_keys(self):
        """Location keys must not be empty."""
        errors = validate_registry({"": {"domain": "test"}})
        assert len(errors) > 0
        assert any("location key must not be empty" in e.error for e in errors)

    def test_rejects_leading_slash(self):
        """Location keys must not start with /."""
        errors = validate_registry({"/cnc": {"domain": "cnc", "tags": [], "topics": [], "allowed_extensions": [".png"]}})
        assert len(errors) > 0
        assert any("leading or trailing slash" in e.error for e in errors)

    def test_rejects_trailing_slash(self):
        """Location keys must not end with /."""
        errors = validate_registry({"cnc/": {"domain": "cnc", "tags": [], "topics": [], "allowed_extensions": [".png"]}})
        assert len(errors) > 0
        assert any("leading or trailing slash" in e.error for e in errors)

    def test_rejects_double_slash(self):
        """Location keys must not contain //."""
        errors = validate_registry({"cnc//design": {"domain": "cnc", "tags": [], "topics": [], "allowed_extensions": [".png"]}})
        assert len(errors) > 0
        assert any("empty path segments" in e.error for e in errors)

    def test_rejects_dot_segments(self):
        """Location keys must not contain . or .. segments."""
        errors1 = validate_registry({"cnc/.": {"domain": "cnc", "tags": [], "topics": [], "allowed_extensions": [".png"]}})
        assert len(errors1) > 0
        assert any("'.' or '..' segments" in e.error for e in errors1)

        errors2 = validate_registry({"cnc/..": {"domain": "cnc", "tags": [], "topics": [], "allowed_extensions": [".png"]}})
        assert len(errors2) > 0
        assert any("'.' or '..' segments" in e.error for e in errors2)

    def test_rejects_unknown_fields(self):
        """Location definitions must not have unknown fields."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": [],
                "topics": [],
                "allowed_extensions": [".png"],
                "unknown_field": "value",
            }
        })
        assert len(errors) > 0
        assert any("unknown field" in e.error for e in errors)

    def test_rejects_empty_tags(self):
        """Tags list must not be empty."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": [],
                "topics": ["cnc"],
                "allowed_extensions": [".png"],
            }
        })
        assert len(errors) > 0
        assert any("tags" in e.path and "empty" in e.error for e in errors)

    def test_rejects_empty_topics(self):
        """Topics list must not be empty."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": [],
                "allowed_extensions": [".png"],
            }
        })
        assert len(errors) > 0
        assert any("topics" in e.path and "empty" in e.error for e in errors)

    def test_rejects_empty_allowed_extensions(self):
        """Allowed extensions list must not be empty."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": ["cnc"],
                "allowed_extensions": [],
            }
        })
        assert len(errors) > 0
        assert any("allowed_extensions" in e.path and "empty" in e.error for e in errors)

    def test_rejects_extension_without_dot(self):
        """Extensions must start with a dot."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": ["cnc"],
                "allowed_extensions": ["png"],
            }
        })
        assert len(errors) > 0
        assert any("allowed_extensions" in e.path and "leading dot" in e.error for e in errors)

    def test_rejects_invalid_filename_rules_case(self):
        """Filename rules case must be 'lower' or 'preserve'."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": ["cnc"],
                "allowed_extensions": [".png"],
                "filename_rules": {"case": "UPPER"},
            }
        })
        assert len(errors) > 0
        assert any("case" in e.path and "lower" in e.error for e in errors)

    def test_rejects_invalid_regex_pattern(self):
        """Filename patterns with invalid regex must be rejected."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": ["cnc"],
                "allowed_extensions": [".png"],
                "filename_rules": {
                    "patterns": [
                        {"name": "version", "regex": "(unclosed"},
                    ],
                },
            }
        })
        assert len(errors) > 0
        assert any("regex" in e.path and "invalid regular expression" in e.error for e in errors)

    def test_detects_duplicate_keys(self):
        """Exact duplicate location keys must be rejected."""
        # Note: We can't test this directly with validate_registry since dict keys are unique
        # But the code path exists to handle malformed JSON that might be parsed differently
        pass

    def test_allows_overlapping_prefixes(self):
        """Overlapping prefixes (longest-prefix matching) are allowed."""
        errors = validate_registry({
            "cnc": {
                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": ["cnc"],
                "allowed_extensions": [".png"],
            },
            "cnc/design": {
                "domain": "cnc",
                "tags": ["manufacturing", "design"],
                "topics": ["cnc", "design"],
                "allowed_extensions": [".svg"],
            },
        })
        assert len(errors) == 0


class TestLongestPrefixMatching:
    """Test longest-prefix matching behavior."""

    def test_matches_exact_location(self, tmp_registry_file):
        """Exact location match."""
        load_registry()
        entry = match_location(["cnc", "file.png"])
        assert entry.key == "cnc"

    def test_matches_deepest_prefix(self, tmp_registry_file):
        """Chooses the longest matching prefix."""
        load_registry()
        entry = match_location(["cnc", "design", "part.svg"])
        assert entry.key == "cnc/design"

    def test_raises_when_no_match(self, tmp_registry_file):
        """Raises LocationNotFoundError when no location matches."""
        load_registry()
        with pytest.raises(LocationNotFoundError):
            match_location(["unknown", "file.png"])

    def test_overlapping_prefixes_pick_longest(self, tmp_registry_file):
        """With overlapping prefixes (cnc, cnc/design), pick the longest."""
        load_registry()
        entry = match_location(["cnc", "design", "subfolder", "file.svg"])
        assert entry.key == "cnc/design"


class TestRegistryLoading:
    """Test registry loading from filesystem."""

    def test_loads_valid_registry(self, tmp_registry_file):
        """Successfully loads a valid registry."""
        registry = load_registry()
        assert "cnc" in registry
        assert "cnc/design" in registry
        assert registry["cnc"].domain == "cnc"

    def test_raises_on_invalid_registry(self, tmp_path: Path, monkeypatch):
        """Raises RegistryValidationException for invalid registry."""
        invalid_registry = tmp_path / "invalid.json"
        invalid_registry.write_text(json.dumps({"cnc": {"domain": "cnc"}}))  # Missing required fields
        monkeypatch.setenv("ARTIFACT_ENGINE_REGISTRY", str(invalid_registry))

        with pytest.raises(RegistryValidationException):
            load_registry()

    def test_raises_on_missing_file(self, tmp_path: Path, monkeypatch):
        """Raises error when registry file doesn't exist."""
        missing = tmp_path / "missing.json"
        monkeypatch.setenv("ARTIFACT_ENGINE_REGISTRY", str(missing))

        with pytest.raises(Exception):
            load_registry()

