                "domain": "cnc",
                "tags": ["manufacturing"],
                "topics": [],
                "allowed_extensions": [".png"],
            }
        })
        assert len(errors) > 0
        assert any("topics" in e.path and "empty" in e.error for e in errors)

    def test_rejects_empty_allowed_extensions(self):
